{"command":"cd /workspace && python - <<'PY'
import sys; sys.path.insert(0, "/tmp")
import json
from tune_lib import make_file, run, show

def mk(lead=None):
    p = {"stat":"median","form":"mult","W":3,"decay":0.7,"shrink":0.2,"bias":0.80,"year_from":1970}
    if lead is not None:
        p["bias_lead_global"] = lead
    return p

grid = [0.80,0.85,0.90,0.95,1.00]
cur = [0.80,0.80,0.80]
r0 = run(make_file("/tmp/c4.py", [mk(None)]))
print("unified:", round(r0["results"][0]["score"],4), r0["results"][0]["by_year"])
for it in range(3):
    improved = False
    for h in range(3):
        cands = [mk(None), mk(cur)]
        for b in grid:
            c = list(cur); c[h] = b
            if c != cur: cands.append(mk(c))
        r = run(make_file("/tmp/c4b.py", cands))
        scs = {tuple((i["params"].get("bias_lead_global") or (0.8,0.8,0.8))): (i["score"], i["by_year"]) for i in r["results"]}
        cursc = scs[tuple(cur)][0]
        bestb, bests = cur, cursc
        for b in grid:
            c = list(cur); c[h] = b; t = tuple(c)
            if t in scs and scs[t][0] > bests:
                bestb, bests = c, scs[t][0]
        if bests > cursc + 1e-9:
            cur, improved = bestb, True
            print(f"iter{it} h={h+1}: {bestb} {round(bests,4)}")
    if not improved: break
r1 = run(make_file("/tmp/c4c.py", [mk(None), mk(cur)]))
for item in r1["results"]:
    print(json.dumps(item["params"]), round(item["score"],4), {k:round(v,4) for k,v in item["by_year"].items()})
u = r1["results"][0]; l = r1["results"][1]
print("delta =", round(l["score"]-u["score"],4),
      "all_years_better =", all(l["by_year"][y] >= u["by_year"][y] for y in u["by_year"]))
PY"}

